          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)==============================================================\nimport java.util.*;\nimport java.io.*;\n\nclass dataList {\n\n    Node head, tail;\n\n    dataList() {\n        head = tail = null;\n    }\n\n    boolean isEmpty() {\n        return (head == null);\n    }\n\n    void clear() {\n        head = tail = null;\n    }\n\n    void loadDataRoom(int k) //do not edit this function\n    {\n        String[] a = Lib.readLineToStrArray(\"data.txt\", k);\n        int[] b = Lib.readLineToIntArray(\"data.txt\", k + 1);\n        int[] c = Lib.readLineToIntArray(\"data.txt\", k + 2);\n        int[] d = Lib.readLineToIntArray(\"data.txt\", k + 3);\n        int n = a.length;\n        for (int i = 0; i < n; i++) {\n            addLast(a[i], b[i], c[i], d[i]);\n        }\n    }\n\n    void addLast(String code, int status, int size, int price) {\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        if (size <= 0 || price <= 0) {\n            return;\n        }\n        Node node = new Node(new Room(code, status, size, price));\n        if (isEmpty()) {\n            head = tail = node;\n        } else {\n            tail.next = node;\n            tail = node;\n        }\n        //---------------------------------------------------------\n    }\n\n}\n\nclass requestQueue {\n\n    Node front, rear;\n\n    requestQueue() {\n        front = rear = null;\n    }\n\n    boolean isEmpty() {\n        return (front == null);\n    }\n\n    void clear() {\n        front = rear = null;\n    }\n\n    void loadDataRequest(int k) //do not edit this function\n    {\n        int[] a = Lib.readLineToIntArray(\"data.txt\", k + 4);\n        int[] b = Lib.readLineToIntArray(\"data.txt\", k + 5);\n        int n = a.length;\n        for (int i = 0; i < n; i++) {\n            enQueue(a[i], b[i]);\n        }\n    }\n\n    void enQueue(int size, int price) {\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        if (size <= 0 || price <= 0) {\n            return;\n        }\n        Node node = new Node(new Room(size, price));\n        if (isEmpty()) {\n            front = rear = node;\n        } else {\n            rear.next = node;\n            rear = node;\n        }\n        //---------------------------------------------------------\n    }\n\n    Room deQueue() {\n        Room tmp = new Room();\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        if (isEmpty()) {\n            return null;\n        }\n        tmp = front.info;\n        front = front.next;\n        if (front == null) {\n            rear = null;\n        }\n        //---------------------------------------------------------\n        return tmp;\n    }\n\n}\n\nclass MyStore {\n\n    dataList dList = new dataList();\n    requestQueue RQueue = new requestQueue();\n\n    MyStore() {\n    }\n\n    void fvisit(Node p, RandomAccessFile f) throws Exception {\n        if (p != null) {\n            f.writeBytes(p.info + \" \");\n        }\n    }\n\n    void ftraverse(RandomAccessFile f) throws Exception {\n        Node p = dList.head;\n        f.writeBytes(\"Data List: \");\n        if (p == null) {\n            f.writeBytes(\"Empty\");\n        }\n        while (p != null) {\n            fvisit(p, f); // You will use this statement to write information of the node p to the file\n            p = p.next;\n        }\n        f.writeBytes(\"\\r\\n\");\n        f.writeBytes(\"Request  : \");\n        p = RQueue.front;\n        if (p == null) {\n            f.writeBytes(\"Empty\");\n        }\n        while (p != null) {\n            f.writeBytes(\"(\" + p.info.getSize() + \",\" + p.info.getPrice() + \") \");\n            p = p.next;\n        }\n        f.writeBytes(\"\\r\\n\");\n    }\n\n    void load(int k) throws Exception //do not edit this function\n    {\n        dList.loadDataRoom(k);\n        RQueue.loadDataRequest(k);\n    }\n\n//===========================================================================\n//=======YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n    void f1() throws Exception {\n        load(1);\n        String fname = \"f1.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        f.close();\n    }\n\n    void rent(Room t) throws Exception {\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        Node p = dList.head;\n        Node best = null;\n        while (p != null) {\n            if (p.info.getStatus() == 0 && p.info.getSize() >= t.getSize() && p.info.getPrice() <= t.getPrice()) {\n                if (best == null || p.info.getPrice() < best.info.getPrice()) {\n                    best = p;\n                }\n            }\n            p = p.next;\n        }\n        if (best != null) {\n            best.info.setStatus(1);\n        }\n        //---------------------------------------------------------\n    }\n\n    void f2() throws Exception {\n        load(1);\n        String fname = \"f2.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        Room req = RQueue.deQueue();\n        if (req != null) {\n            rent(req);\n        }\n        //---------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n    void f3() throws Exception {\n        load(1);\n        String fname = \"f3.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        while (!RQueue.isEmpty()) {\n            Room req = RQueue.deQueue();\n            if (req != null) {\n                rent(req);\n            }\n        }\n        //---------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n    void f4() throws Exception {\n        load(1);\n        String fname = \"f4.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        int count = 0;\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        while (!RQueue.isEmpty()) {\n            Room req = RQueue.deQueue();\n            if (req != null) {\n                rent(req);\n            }\n        }\n        Node p = dList.head;\n        while (p != null) {\n            if (p.info.getStatus() == 0) count++;\n            p = p.next;\n        }\n        //---------------------------------------------------------\n        ftraverse(f);\n        f.writeBytes(\"Available Room(s): \" + count + \" \");\n        f.close();\n    }\n\n}\n",
